-- =========================================================================
-- MRWATER: CREATE CUSTOMERS TABLE & UPDATE BEATS IN SUPABASE POSTGRESQL
-- Run this query in Supabase: Dashboard -> SQL Editor -> New Query -> Run
-- =========================================================================

-- 1. CREATE CUSTOMERS TABLE IN SUPABASE
CREATE TABLE IF NOT EXISTS public.customers (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    phone TEXT DEFAULT '',
    city TEXT DEFAULT '',
    route TEXT DEFAULT '',
    beat_id TEXT DEFAULT '',
    opening_balance NUMERIC(12, 2) DEFAULT 0,
    credit_limit NUMERIC(12, 2) DEFAULT 0,
    notes TEXT DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable RLS on customers
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow all access to customers" ON public.customers;
CREATE POLICY "Allow all access to customers" ON public.customers FOR ALL USING (true) WITH CHECK (true);

-- 2. UPDATE BEAT DEFINITIONS IN ORGANIZATION PROFILE & APP COLLECTIONS
UPDATE public.organization_profile
SET data = jsonb_set(COALESCE(data, '{}'::jsonb), '{beats}', '[{"id":"beat_mw22aon9905q","hub":"Kuchinda","name":"Kuchinda Town","label":"Kuchinda Town","stops":[],"active":true},{"id":"beat_mw24x4jj4jvg","hub":"Kuchinda","name":"Kusumi","label":"Kusumi","stops":[],"active":true},{"id":"beat_mw24xvfh21zw","hub":"Kuchinda","name":"Keseibahal","label":"Keseibahal","stops":[],"active":true},{"id":"beat_mw24yeqi4nu3","hub":"Kuchinda","name":"Jamankira","label":"Jamankira","stops":[],"active":true},{"id":"beat_mw24ysatjevj","hub":"Kuchinda","name":"Laida","label":"Laida","stops":[],"active":true},{"id":"beat_mw77386qabat","hub":"Kuchinda","name":"Malidihi","label":"Malidihi","stops":[],"active":true}]'::jsonb, true),
    updated_at = NOW()
WHERE id = 'default';

